1	/**
2	 * Shared-hosting account provisioner (Phase 1).
3	 *
4	 * ┌────────────────────────────────────────────────────────────────────────┐
5	 * │ SAFETY POSTURE — READ BEFORE ENABLING                                    │
6	 * │                                                                          │
7	 * │ This provisions UNTRUSTED customers side-by-side on ONE box. The         │
8	 * │ isolation shell (jailed user + per-user PHP-FPM pool + open_basedir +    │
9	 * │ disk quota + scoped DB + chrooted SFTP) is the standard Hestia/cPanel    │
10	 * │ model, but multi-tenant isolation is the one place a subtle gap is a     │
11	 * │ CROSS-CUSTOMER BREACH. So the whole provisioner is INERT unless          │
12	 * │ `ENABLE_SHARED_HOSTING=1` AND not SANDBOX. Do NOT flip that flag in      │
13	 * │ production until this has been (1) reviewed as a security change,        │
14	 * │ (2) validated end-to-end on a dedicated STAGING shared node,             │
15	 * │ (3) paired with fail2ban + ModSecurity + a malware scanner.             │
16	 * │                                                                          │
17	 * │ The sshd change (SFTP chroot) is `sshd -t`-validated BEFORE any reload,  │
18	 * │ so a bad config can never lock the box out — but it still deserves the   │
19	 * │ staging pass.                                                            │
20	 * └────────────────────────────────────────────────────────────────────────┘
21	 *
22	 * Everything a shell touches is validated through the tested pure helpers in
23	 * lib/hosting.ts BEFORE interpolation.
24	 */
25	
26	import { Client } from "ssh2";
27	import { randomBytes } from "node:crypto";
28	import { promises as dns } from "node:dns";
29	import { db } from "../lib/db";
30	import { SANDBOX } from "../lib/sandbox";
31	import { decryptSecret, encryptSecret } from "../lib/crypto-box";
32	import {
33	  isValidUnixUsername,
34	  isValidHostingDomain,
35	  isValidSubdomainLabel,
36	  isValidCronSchedule,
37	  isValidCronCommand,
38	  subdomainPaths,
39	  addonDomainPaths,
40	  planLimits,
41	  diskQuotaBlocks,
42	  accountPaths,
43	  accountFsPlan,
44	  fpmPoolConfig,
45	  buildScopedGrantSql,
46	  selfSignedCertDir,
47	} from "../lib/hosting";
48	
49	/** Shell-escape the raw SQL from buildScopedGrantSql for embedding in a
50	 *  double-quoted `mysql -e "..."`. Identifiers/passwords are already validated
51	 *  to safe charsets; only the SQL's own backticks need escaping so the shell
52	 *  doesn't treat them as command substitution. */
53	function sqlForMysqlExec(sql: string): string {
54	  return sql.replace(/`/g, "\\`");
55	}
56	
57	const ENABLED = process.env.ENABLE_SHARED_HOSTING === "1";
58	const CONNECT_TIMEOUT_MS = 20_000;
59	const STEP_TIMEOUT_MS = 60_000;
60	
61	/** Alphanumeric password (shell/SQL-safe: no quoting hazards). */
62	function strongPassword(len = 22): string {
63	  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
64	  const bytes = randomBytes(len);
65	  let out = "";
66	  for (let i = 0; i < len; i++) out += alphabet[bytes[i] % alphabet.length];
67	  return out;
68	}
69	
70	async function connectNode(node: { sshHost: string; sshPort: number; rootPasswordEnc: string | null }): Promise<Client> {
71	  const password = node.rootPasswordEnc ? decryptSecret(node.rootPasswordEnc) : "";
72	  if (!password) throw new Error("Hosting node has no root credential on record.");
73	  const conn = new Client();
74	  await new Promise<void>((resolve, reject) => {
75	    const timer = setTimeout(() => { try { conn.end(); } catch { /* */ } reject(new Error("SSH connect timed out")); }, CONNECT_TIMEOUT_MS);
76	    conn
77	      .on("ready", () => { clearTimeout(timer); resolve(); })
78	      .on("error", (e) => { clearTimeout(timer); reject(e); })
79	      .connect({ host: node.sshHost, port: node.sshPort, username: "root", password, readyTimeout: CONNECT_TIMEOUT_MS });
80	  });
81	  return conn;
82	}
83	
84	function exec(conn: Client, command: string, timeoutMs = STEP_TIMEOUT_MS): Promise<{ code: number; out: string }> {
85	  return new Promise((resolve, reject) => {
86	    const timer = setTimeout(() => reject(new Error("command timed out")), timeoutMs);
87	    conn.exec(command, (err, stream) => {
88	      if (err) { clearTimeout(timer); return reject(err); }
89	      let out = "";
90	      stream
91	        .on("close", (code: number) => { clearTimeout(timer); resolve({ code: code ?? 0, out }); })
92	        .on("data", (d: Buffer) => { out += d.toString(); })
93	        .stderr.on("data", (d: Buffer) => { out += d.toString(); });
94	    });
95	  });
96	}
97	
98	async function run(conn: Client, label: string, cmd: string): Promise<void> {
99	  const r = await exec(conn, cmd, STEP_TIMEOUT_MS);
100	  if (r.code !== 0) throw new Error(`${label} failed: ${r.out.slice(0, 300)}`);
101	}
102	
103	/**
104	 * The name-based nginx vhost for one account. It ALWAYS emits a `listen 443 ssl`
105	 * server block so nginx answers HTTPS from the moment the account exists —
106	 * `ssl.certDir` is the real Let's Encrypt live dir when `ssl.real` is true, else
107	 * the per-account SELF-SIGNED fallback generated at provision time. That is the
108	 * whole "clean setup always" guarantee: HTTPS shows a cert WARNING, never
109	 * ERR_CONNECTION_REFUSED. The HTTP→HTTPS redirect fires ONLY once a real cert
110	 * exists; a self-signed site still serves its body over both 80 and 443 (so it
111	 * can't 301-loop a visitor into an untrusted-cert dead end). Shared IP; routed
112	 * purely by server_name; PHP proxied to THIS account's socket only, root jailed to
113	 * its webroot. Pure string — no interpolation reaches a shell here.
114	 */
115	function renderHostingVhost(username: string, domain: string, webroot: string, sock: string, ssl: { certDir: string; real: boolean }): string {
116	  const phpLoc = [
117	    `    location ~ \\.php$ {`,
118	    `        include fastcgi_params;`,
119	    `        fastcgi_pass unix:${sock};`,
120	    `        fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;`,
121	    `    }`,
122	  ].join("\n");
123	  const body = [
124	    `    root ${webroot};`,
125	    `    index index.php index.html;`,
126	    `    location / { try_files $uri $uri/ /index.php?$query_string; }`,
127	    phpLoc,
128	    `    location ~ /\\. { deny all; }`,
129	  ].join("\n");
130	  const http = [
131	    `server {`,
132	    `    listen 80;`,
133	    `    listen [::]:80;`,
134	    `    server_name ${domain} www.${domain};`,
135	    `    location ^~ /.well-known/acme-challenge/ { root /var/www/html; }`,
136	    // Redirect to HTTPS only with a REAL cert; a self-signed site serves over 80 too.
137	    ssl.real ? `    location / { return 301 https://$host$request_uri; }` : body,
138	    `}`,
139	  ].join("\n");
140	  const https = [
141	    `server {`,
142	    `    listen 443 ssl;`,
143	    `    listen [::]:443 ssl;`,
144	    `    server_name ${domain} www.${domain};`,
145	    `    ssl_certificate ${ssl.certDir}/fullchain.pem;`,
146	    `    ssl_certificate_key ${ssl.certDir}/privkey.pem;`,
147	    `    ssl_protocols TLSv1.2 TLSv1.3;`,
148	    body,
149	    `}`,
150	  ].join("\n");
151	  return `${http}\n${https}\n`;
152	}
153	
154	/** Write a vhost file + enable it, tested before reload. */
155	async function installVhost(conn: Client, username: string, conf: string): Promise<void> {
156	  const path = `/etc/nginx/sites-available/hosting-${username}.conf`;
157	  await run(conn, "write vhost", `cat > ${path} <<'VH'\n${conf}VH\nln -sfn ${path} /etc/nginx/sites-enabled/hosting-${username}.conf`);
158	  await run(conn, "test + reload nginx", `nginx -t && systemctl reload nginx`);
159	}
160	
161	/**
162	 * A single extra site (subdomain / addon domain): its own docroot + PHP socket,
163	 * one `server_name`. Same shape as renderHostingVhost but keyed on an explicit
164	 * server_name string so it can serve a subdomain OR an addon domain. Pure — no
165	 * interpolation reaches a shell here (the caller validated every part).
166	 */
167	function renderSiteVhost(serverName: string, docroot: string, sock: string, sslLiveDir: string | null): string {
168	  const phpLoc = [
169	    `    location ~ \\.php$ {`,
170	    `        include fastcgi_params;`,
171	    `        fastcgi_pass unix:${sock};`,
172	    `        fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;`,
173	    `    }`,
174	  ].join("\n");
175	  const body = [
176	    `    root ${docroot};`,
177	    `    index index.php index.html;`,
178	    `    location / { try_files $uri $uri/ /index.php?$query_string; }`,
179	    phpLoc,
180	    `    location ~ /\\. { deny all; }`,
181	  ].join("\n");
182	  const http = [
183	    `server {`,
184	    `    listen 80;`,
185	    `    listen [::]:80;`,
186	    `    server_name ${serverName};`,
187	    `    location ^~ /.well-known/acme-challenge/ { root /var/www/html; }`,
188	    sslLiveDir ? `    location / { return 301 https://$host$request_uri; }` : body,
189	    `}`,
190	  ].join("\n");
191	  if (!sslLiveDir) return http + "\n";
192	  const https = [
193	    `server {`,
194	    `    listen 443 ssl;`,
195	    `    listen [::]:443 ssl;`,
196	    `    server_name ${serverName};`,
197	    `    ssl_certificate ${sslLiveDir}/fullchain.pem;`,
198	    `    ssl_certificate_key ${sslLiveDir}/privkey.pem;`,
199	    `    ssl_protocols TLSv1.2 TLSv1.3;`,
200	    body,
201	    `}`,
202	  ].join("\n");
203	  return `${http}\n${https}\n`;
204	}
205	
206	/** Write + enable a vhost under an arbitrary key (hosting-<key>.conf), tested
207	 *  before reload. Used for subdomain / addon-domain sites (key = <user>-<label>
208	 *  or <user>-<domain>); the account's own primary vhost keeps its <user> filename. */
209	async function installNamedVhost(conn: Client, key: string, conf: string): Promise<void> {
210	  const path = `/etc/nginx/sites-available/hosting-${key}.conf`;
211	  await run(conn, "write site vhost", `cat > ${path} <<'VH'\n${conf}VH\nln -sfn ${path} /etc/nginx/sites-enabled/hosting-${key}.conf`);
212	  await run(conn, "test + reload nginx", `nginx -t && systemctl reload nginx`);
213	}
214	
215	/** Remove a named site vhost (enabled + available), tested before reload. */
216	async function removeNamedVhost(conn: Client, key: string): Promise<void> {
217	  await run(conn, "remove site vhost", `rm -f /etc/nginx/sites-enabled/hosting-${key}.conf /etc/nginx/sites-available/hosting-${key}.conf; nginx -t && systemctl reload nginx || true`);
218	}
219	
220	/** Write + (re)load an account's FPM pool for a given PHP version. The pool
221	 *  contents (the PHP isolation boundary) come from the tested pure generator in
222	 *  lib/hosting.ts — socket path is unchanged across versions so the vhost never
223	 *  needs editing when PHP is switched. */
224	async function writeFpmPool(conn: Client, u: string, home: string, webroot: string, php: string): Promise<void> {
225	  if (!/^\d\.\d$/.test(php)) throw new Error(`refusing unsafe php version ${php}`);
226	  await run(conn, "php-fpm pool", `cat > /etc/php/${php}/fpm/pool.d/${u}.conf <<'POOL'\n${fpmPoolConfig(u, home, webroot)}\nPOOL\nsystemctl reload php${php}-fpm 2>/dev/null || systemctl restart php${php}-fpm`);
227	}
228	
229	/**
230	 * The isolation shell for one account (HTTP-only vhost; SSL added later by the
231	 * sweep once DNS points at us). Every interpolated value has already cleared a
232	 * validator, so nothing here can be a shell metacharacter.
233	 */
234	async function applyIsolation(
235	  conn: Client,
236	  a: { username: string; primaryDomain: string; diskQuotaMB: number; sftpPassword: string },
237	  php: string,
238	): Promise<void> {
239	  const u = a.username;
240	  const d = a.primaryDomain;
241	  if (!isValidUnixUsername(u)) throw new Error(`refusing unsafe username ${u}`);
242	  if (!isValidHostingDomain(d)) throw new Error(`refusing unsafe domain ${d}`);
243	  if (!/^\d\.\d$/.test(php)) throw new Error(`refusing unsafe php version ${php}`);
244	  const { home, webroot } = accountPaths(u);
245	  const hardBlocks = diskQuotaBlocks(Math.max(1, Math.round(a.diskQuotaMB / 1024)));
246	  const softBlocks = Math.floor(hardBlocks * 0.95);
247	  const sock = `/run/php/${u}.sock`;
248	
249	  // 1. Jailed user. Home is ROOT-owned (a chroot requirement); the user owns only
250	  //    public_html + tmp under it. nologin shell — SFTP-only via the chroot below.
251	  //
252	  // Perms come from the tested accountFsPlan(): home 711 (chroot-safe + nginx can
253	  // TRAVERSE to the webroot but a peer tenant can't LIST the home), webroot
254	  // 2750 <user>:www-data (nginx reads via the www-data GROUP, never world — the
255	  // old world-readable 755 let any tenant read a neighbour's wp-config.php if
256	  // open_basedir was escaped; the setgid bit keeps tenant-created files in the
257	  // www-data group so nginx keeps serving them), tmp 700 (private PHP scratch).
258	  const fs = accountFsPlan(u);
259	  await run(conn, "create user", `id -u ${u} >/dev/null 2>&1 || useradd -m -d ${home} -s /usr/sbin/nologin ${u}`);
260	  await run(
261	    conn,
262	    "chroot-safe home",
263	    `mkdir -p ${webroot} ${home}/tmp && ` +
264	      `chown ${fs.home.owner} ${home} && chmod ${fs.home.mode} ${home} && ` +
265	      `chown ${fs.webroot.owner} ${webroot} && chmod ${fs.webroot.mode} ${webroot} && ` +
266	      `chown ${fs.tmp.owner} ${home}/tmp && chmod ${fs.tmp.mode} ${home}/tmp`,
267	  );
268	  await run(conn, "sftp password", `printf '%s:%s' ${u} '${a.sftpPassword}' | chpasswd`);
269	
270	  // 2. Disk quota (fs must have usrquota — node onboarding enables it).
271	  await run(conn, "disk quota", `command -v setquota >/dev/null 2>&1 && setquota -u ${u} ${softBlocks} ${hardBlocks} 0 0 /home || echo 'quota tool absent — skipped'`);
272	
273	  // 3. Per-user PHP-FPM pool — THE PHP isolation boundary.
274	  await writeFpmPool(conn, u, home, webroot, php);
275	
276	  // 4. Self-signed FALLBACK cert, so nginx can listen on 443 from the very first
277	  //    second the account exists. Without this the account served HTTP-only until
278	  //    the SSL sweep ran, and any visitor hitting https:// got ERR_CONNECTION_REFUSED
279	  //    while the panel already said "active" (the kaymo failure). Idempotent: only
280	  //    generated if absent. Key is 600 root; the whole dir is root-owned + off the
281	  //    tenant tree, so a tenant can never read or swap its own TLS key.
282	  const ssCertDir = selfSignedCertDir(u);
283	  await run(
284	    conn,
285	    "self-signed fallback cert",
286	    `mkdir -p ${ssCertDir} && chmod 700 ${ssCertDir} && ` +
287	      `if [ ! -s ${ssCertDir}/fullchain.pem ] || [ ! -s ${ssCertDir}/privkey.pem ]; then ` +
288	      `openssl req -x509 -newkey rsa:2048 -nodes -keyout ${ssCertDir}/privkey.pem -out ${ssCertDir}/fullchain.pem ` +
289	      `-days 3650 -subj "/CN=${d}" -addext "subjectAltName=DNS:${d},DNS:www.${d}"; fi && ` +
290	      `chown -R root:root ${ssCertDir} && chmod 600 ${ssCertDir}/privkey.pem && chmod 644 ${ssCertDir}/fullchain.pem`,
291	  );
292	
293	  // 5. Name-based vhost — ALWAYS listens on 443, using the self-signed fallback
294	  //    until the SSL sweep swaps in the real Let's Encrypt cert.
295	  await installVhost(conn, u, renderHostingVhost(u, d, webroot, sock, { certDir: ssCertDir, real: false }));
296	
297	  // 6. Chrooted SFTP — sshd -t GUARDED so a bad config can never lock out the box.
298	  const sftpConf = [
299	    `Match User ${u}`,
300	    `    ChrootDirectory ${home}`,
301	    `    ForceCommand internal-sftp`,
302	    `    AllowTcpForwarding no`,
303	    `    X11Forwarding no`,
304	  ].join("\n");
305	  const sshdFile = `/etc/ssh/sshd_config.d/nxeon-${u}.conf`;
306	  await run(
307	    conn,
308	    "sftp chroot (guarded)",
309	    // Write to a temp include, validate the WHOLE sshd config, and only then move
310	    // it into place + reload. If sshd -t fails, discard — never reload a broken config.
311	    `mkdir -p /etc/ssh/sshd_config.d && cat > ${sshdFile}.new <<'SSHD'\n${sftpConf}\nSSHD\n` +
312	      `cp -f ${sshdFile}.new ${sshdFile} && if sshd -t 2>/dev/null; then systemctl reload ssh 2>/dev/null || systemctl reload sshd; else rm -f ${sshdFile}; echo 'sshd -t rejected the chroot block — SFTP not enabled, box untouched'; fi; rm -f ${sshdFile}.new`,
313	  );
314	}
315	
316	// ---- DB provisioning (per-account, on demand) ------------------------------
317	
318	/** Create ONE scoped MySQL/MariaDB user+db on the account's node. */
319	async function provisionHostingDatabase(dbId: string): Promise<void> {
320	  const rec = await db.hostingDatabase.findUnique({ where: { id: dbId }, include: { account: { include: { node: true } } } });
321	  if (!rec || rec.status !== "PENDING") return;
322	  if (SANDBOX || !ENABLED) {
323	    await db.hostingDatabase.update({ where: { id: rec.id }, data: { status: SANDBOX ? "ACTIVE" : "PENDING", passwordEnc: null, error: SANDBOX ? null : "Shared hosting not enabled." } });
324	    return;
325	  }
326	  const name = rec.name;
327	  const user = rec.dbUser;
328	  const pass = rec.passwordEnc ? decryptSecret(rec.passwordEnc) : "";
329	  // DB name + user were built from the validated username; re-assert shape.
330	  if (!/^[a-z0-9_]{1,64}$/.test(name) || !/^[a-z0-9_]{1,32}$/.test(user) || !pass) {
331	    await db.hostingDatabase.update({ where: { id: rec.id }, data: { status: "FAILED", error: "invalid db identifiers" } });
332	    return;
333	  }
334	  try {
335	    const conn = await connectNode(rec.account.node);
336	    try {
337	      // Grants scoped to THIS database only — the data-isolation boundary.
338	      // buildScopedGrantSql escapes _/% so the GRANT can't bleed onto a peer's db.
339	      const sql = sqlForMysqlExec(buildScopedGrantSql(name, user, pass));
340	      await run(conn, "create database", `mysql -e "${sql}"`);
341	    } finally {
342	      try { conn.end(); } catch { /* */ }
343	    }
344	    await db.hostingDatabase.update({ where: { id: rec.id }, data: { status: "ACTIVE", passwordEnc: null, error: null } });
345	  } catch (e) {
346	    await db.hostingDatabase.update({ where: { id: rec.id }, data: { status: "FAILED", error: (e instanceof Error ? e.message : String(e)).slice(0, 300) } });
347	  }
348	}
349	
350	export async function hostingDatabaseSweep(): Promise<void> {
351	  const pending = await db.hostingDatabase.findMany({ where: { status: "PENDING" }, select: { id: true }, take: 10 });
352	  for (const p of pending) await provisionHostingDatabase(p.id).catch((e) => console.error(`[hosting] db ${p.id} failed`, e));
353	}
354	
355	// ---- Account provisioning --------------------------------------------------
356	
357	export async function provisionHostingAccount(accountId: string): Promise<void> {
358	  const account = await db.hostingAccount.findUnique({ where: { id: accountId }, include: { node: true, plan: true } });
359	  if (!account || account.status !== "PENDING") return;
360	  await db.hostingAccount.update({ where: { id: account.id }, data: { status: "PROVISIONING", error: null } });
361	
362	  if (SANDBOX || !ENABLED) {
363	    if (SANDBOX) {
364	      const pw = strongPassword();
365	      await db.hostingAccount.update({ where: { id: account.id }, data: { status: "ACTIVE", provisionedAt: new Date(), sftpPasswordEnc: encryptSecret(pw), error: null } });
366	    } else {
367	      await db.hostingAccount.update({ where: { id: account.id }, data: { status: "PENDING", error: "Shared hosting is not enabled on this deployment yet." } });
368	    }
369	    return;
370	  }
371	
372	  try {
373	    const allowed = planLimits(account.plan).phpVersions;
374	    const php = allowed.includes(account.phpVersion) ? account.phpVersion : allowed[0];
375	    const sftpPassword = strongPassword();
376	    const conn = await connectNode(account.node);
377	    try {
378	      await applyIsolation(conn, { username: account.username, primaryDomain: account.primaryDomain, diskQuotaMB: account.diskQuotaMB, sftpPassword }, php);
379	    } finally {
380	      try { conn.end(); } catch { /* */ }
381	    }
382	    await db.hostingAccount.update({ where: { id: account.id }, data: { status: "ACTIVE", provisionedAt: new Date(), sftpPasswordEnc: encryptSecret(sftpPassword), error: null } });
383	  } catch (e) {
384	    await db.hostingAccount.update({ where: { id: account.id }, data: { status: "FAILED", error: (e instanceof Error ? e.message : String(e)).slice(0, 300) } });
385	  }
386	}
387	
388	export async function hostingProvisionSweep(): Promise<void> {
389	  const pending = await db.hostingAccount.findMany({ where: { status: "PENDING" }, select: { id: true }, take: 10 });
390	  for (const p of pending) await provisionHostingAccount(p.id).catch((e) => console.error(`[hosting] provision ${p.id} failed`, e));
391	}
392	
393	// ---- SSL sweep (post-DNS, no sshd risk) ------------------------------------
394	
395	/** True once `domain` resolves (A) to the node's shared IP — DNS is pointed at us. */
396	async function domainPointsAt(domain: string, ip: string): Promise<boolean> {
397	  try {
398	    const a = await dns.resolve4(domain);
399	    return a.includes(ip);
400	  } catch {
401	    return false;
402	  }
403	}
404	
405	/**
406	 * For each ACTIVE account without HTTPS, once its domain resolves to the node's
407	 * shared IP, issue a per-domain cert (webroot) and upgrade the vhost to a 443 SNI
408	 * block. Safe: touches only nginx + certbot, never sshd.
409	 */
410	export async function hostingSslSweep(): Promise<void> {
411	  if (SANDBOX || !ENABLED) return;
412	  const accts = await db.hostingAccount.findMany({
413	    where: { status: "ACTIVE", sslActive: false },
414	    include: { node: true },
415	    take: 20,
416	  });
417	  for (const a of accts) {
418	    try {
419	      if (!isValidHostingDomain(a.primaryDomain) || !isValidUnixUsername(a.username)) continue;
420	      if (!(await domainPointsAt(a.primaryDomain, a.node.publicIp))) continue; // DNS not pointed yet
421	      const d = a.primaryDomain;
422	      const conn = await connectNode(a.node);
423	      try {
424	        const issue = await exec(conn, `certbot certonly --webroot -w /var/www/html -d ${d} -d www.${d} --allow-subset-of-names --non-interactive --agree-tos --register-unsafely-without-email --keep-until-expiring 2>&1`, 3 * 60_000);
425	        const liveDir = `/etc/letsencrypt/live/${d}`;
426	        const have = await exec(conn, `test -s ${liveDir}/fullchain.pem && echo yes || echo no`);
427	        if (have.out.trim() !== "yes") { console.log(`[hosting] cert for ${d} not issued yet: ${issue.out.slice(0, 160)}`); continue; }
428	        const { webroot } = accountPaths(a.username);
429	        await installVhost(conn, a.username, renderHostingVhost(a.username, d, webroot, `/run/php/${a.username}.sock`, { certDir: liveDir, real: true }));
430	      } finally {
431	        try { conn.end(); } catch { /* */ }
432	      }
433	      await db.hostingAccount.update({ where: { id: a.id }, data: { sslActive: true } });
434	      console.log(`[hosting] HTTPS active for ${a.primaryDomain}`);
