504	// ---- Serve-verification + self-heal health sweep ---------------------------
505	
506	/** Parse the numeric HTTP status curl printed with `-w '%{http_code}'`. Returns 0
507	 *  when curl couldn't get a response (connection refused/timeout → "000"). */
508	function parseHttpCode(out: string): number {
509	  const n = parseInt(out.trim().slice(-3), 10);
510	  return Number.isFinite(n) ? n : 0;
511	}
512	/** A 2xx/3xx means nginx actually answered with a page/redirect for this vhost —
513	 *  the anti-ERR_CONNECTION_REFUSED signal. 4xx/5xx/000 are NOT counted as serving
514	 *  (we never mark an account falsely healthy). */
515	function servesOk(code: number): boolean {
516	  return code >= 200 && code < 400;
517	}
518	
519	/**
520	 * Serve-verification + self-heal for ACTIVE accounts. From the node itself it
521	 * curls http/https for each account's own Host header and records whether nginx
522	 * genuinely answers on 80/443 (serveHttpOk / serveHttpsOk) — so the panel reflects
523	 * REALITY, never "active" while HTTPS refuses (the kaymo failure). It also
524	 * SELF-HEALS: if a real Let's Encrypt cert exists but 443 isn't serving, it
525	 * reinstalls the real-cert vhost and reloads nginx; if HTTPS just isn't issued yet
526	 * it's left to hostingSslSweep. Gated ENABLED && !SANDBOX like every other node
527	 * path. `onlyRequested` processes just the accounts a customer clicked "Check now"
528	 * on (recheckRequested), so the button feels immediate; the full sweep runs on the
529	 * ~10-min tick. Returns the number of accounts processed.
530	 */
531	export async function hostingHealthSweep(opts: { onlyRequested?: boolean } = {}): Promise<number> {
532	  const onlyRequested = opts.onlyRequested === true;
533	  if (SANDBOX) {
534	    // Simulate a healthy check so the dev panel + the "Check now" button resolve,
535	    // and the recheck flag clears. HTTPS "verified" mirrors the (simulated) sslActive.
536	    const accts = await db.hostingAccount.findMany({
537	      where: onlyRequested ? { status: "ACTIVE", recheckRequested: true } : { status: "ACTIVE" },
538	      select: { id: true, sslActive: true },
539	      take: onlyRequested ? 25 : 50,
540	    });
541	    for (const a of accts) {
542	      await db.hostingAccount.update({
543	        where: { id: a.id },
544	        data: {
545	          serveHttpOk: true,
546	          serveHttpsOk: true,
547	          healthNote: a.sslActive ? "HTTPS live — verified" : "HTTP live, HTTPS issuing",
548	          healthCheckedAt: new Date(),
549	          recheckRequested: false,
550	        },
551	      }).catch(() => undefined);
552	    }
553	    return accts.length;
554	  }
555	  if (!ENABLED) return 0;
556	
557	  const accts = await db.hostingAccount.findMany({
558	    where: onlyRequested ? { status: "ACTIVE", recheckRequested: true } : { status: "ACTIVE" },
559	    include: { node: true },
560	    // Newest-requested first so a customer who just clicked "Check now" is served
561	    // before the routine backlog even in the full sweep.
562	    orderBy: [{ recheckRequested: "desc" }, { updatedAt: "asc" }],
563	    take: onlyRequested ? 25 : 30,
564	  });
565	  let processed = 0;
566	  for (const a of accts) {
567	    try {
568	      if (!isValidHostingDomain(a.primaryDomain) || !isValidUnixUsername(a.username)) continue;
569	      const d = a.primaryDomain;
570	      const u = a.username;
571	      let serveHttpOk = false;
572	      let serveHttpsOk = false;
573	      let sslActive = a.sslActive;
574	      let note = "";
575	      const conn = await connectNode(a.node);
576	      try {
577	        const httpR = await exec(conn, `curl -s -o /dev/null -w '%{http_code}' --max-time 8 -H 'Host: ${d}' http://127.0.0.1/ 2>/dev/null || echo 000`, 20_000);
578	        const httpsR = await exec(conn, `curl -sk -o /dev/null -w '%{http_code}' --max-time 8 -H 'Host: ${d}' https://127.0.0.1/ 2>/dev/null || echo 000`, 20_000);
579	        serveHttpOk = servesOk(parseHttpCode(httpR.out));
580	        serveHttpsOk = servesOk(parseHttpCode(httpsR.out));
581	
582	        // Does a REAL Let's Encrypt cert exist on the node for this domain?
583	        const liveDir = `/etc/letsencrypt/live/${d}`;
584	        const haveReal = (await exec(conn, `test -s ${liveDir}/fullchain.pem && echo yes || echo no`)).out.trim() === "yes";
585	
586	        // SELF-HEAL: a real cert exists but 443 isn't serving → the vhost is stale
587	        // or nginx dropped the block. Reinstall the real-cert vhost + reload, then
588	        // re-verify. This is the recovery from exactly the state kaymo hit.
589	        if (haveReal && !serveHttpsOk) {
590	          const { webroot } = accountPaths(u);
591	          try {
592	            await installVhost(conn, u, renderHostingVhost(u, d, webroot, `/run/php/${u}.sock`, { certDir: liveDir, real: true }));
593	            const reR = await exec(conn, `curl -sk -o /dev/null -w '%{http_code}' --max-time 8 -H 'Host: ${d}' https://127.0.0.1/ 2>/dev/null || echo 000`, 20_000);
594	            serveHttpsOk = servesOk(parseHttpCode(reR.out));
595	            if (serveHttpsOk) note = "Recovered HTTPS (reinstalled certificate vhost)";
596	          } catch (e) {
597	            note = "HTTPS repair failed — support notified";
598	            console.error(`[hosting] health self-heal ${a.id} failed`, e);
599	          }
600	        }
601	        if (haveReal && serveHttpsOk) sslActive = true; // real cert is live
602	
603	        if (!note) {
604	          if (sslActive && serveHttpsOk) note = "HTTPS live — verified";
605	          else if (serveHttpsOk || serveHttpOk) note = "HTTP live, HTTPS issuing";
606	          else {
607	            // Nothing served locally. If DNS isn't pointed at us yet, say so;
608	            // otherwise it's a serving fault the SSL sweep / support will chase.
609	            const pointed = await domainPointsAt(d, a.node.publicIp);
610	            note = pointed ? "Serving issue — being checked" : "DNS not detected yet";
611	          }
612	        }
613	      } finally {
614	        try { conn.end(); } catch { /* */ }
615	      }
616	      await db.hostingAccount.update({
617	        where: { id: a.id },
618	        data: { serveHttpOk, serveHttpsOk, sslActive, healthNote: note.slice(0, 200), healthCheckedAt: new Date(), recheckRequested: false },
619	      });
620	      processed++;
621	    } catch (e) {
622	      console.error(`[hosting] health sweep ${a.id} failed`, e);
623	      // Clear the recheck flag even on failure so a broken node can't wedge the
624	      // fast path into re-processing the same account every 30s forever.
625	      await db.hostingAccount.update({ where: { id: a.id }, data: { recheckRequested: false } }).catch(() => undefined);
626	    }
627	  }
628	  return processed;
629	}
