640	/** Move an account's FPM pool to a new PHP version (socket path is unchanged, so
641	 *  the vhost never needs editing). */
642	async function taskPhpSwitch(conn: Client, a: { id: string; username: string; phpVersion: string }, payload: string | null): Promise<void> {
643	  const version = String(JSON.parse(payload || "{}").version ?? "");
644	  if (!/^\d\.\d$/.test(version)) throw new Error("invalid php version");
645	  const { home, webroot } = accountPaths(a.username);
646	  if (version !== a.phpVersion) {
647	    await run(conn, "remove old pool", `rm -f /etc/php/${a.phpVersion}/fpm/pool.d/${a.username}.conf; systemctl reload php${a.phpVersion}-fpm 2>/dev/null || true`);
648	  }
649	  await writeFpmPool(conn, a.username, home, webroot, version);
650	  await db.hostingAccount.update({ where: { id: a.id }, data: { phpVersion: version } });
651	}
