653	// ---- Account lifecycle (suspend / unsuspend / terminate) --------------------
654	// All three validate the username first (it flows into shell), and are written to
655	// be idempotent + safe to re-run. They only touch this account's own files.
656	
657	type LifecycleAccount = { id: string; username: string; phpVersion: string };
658	
659	// Validate BOTH shell-bound fields up front. username is a strict allowlist;
660	// phpVersion is stored (schema default "8.3") but re-checked here so it can never
661	// carry anything but `\d.\d` into an `rm`/`systemctl` line (security audit LOW-1).
662	function assertLifecycleSafe(a: LifecycleAccount): void {
663	  if (!isValidUnixUsername(a.username)) throw new Error("unsafe account username");
664	  if (!/^\d\.\d$/.test(a.phpVersion)) throw new Error("unsafe php version");
665	}
666	
667	/** Take an account OFFLINE without destroying data: drop the nginx site, remove
668	 *  the FPM pool (no PHP), and lock the unix user (no SFTP/login). Reversible. */
669	async function taskSuspend(conn: Client, a: LifecycleAccount): Promise<void> {
670	  assertLifecycleSafe(a);
671	  await run(conn, "suspend: disable vhost", `rm -f /etc/nginx/sites-enabled/hosting-${a.username}.conf; nginx -t && systemctl reload nginx || true`);
672	  await run(conn, "suspend: remove fpm pool", `rm -f /etc/php/${a.phpVersion}/fpm/pool.d/${a.username}.conf; systemctl reload php${a.phpVersion}-fpm 2>/dev/null || true`);
673	  await run(conn, "suspend: lock user", `usermod -L ${a.username} 2>/dev/null || true; pkill -u ${a.username} 2>/dev/null || true`);
674	}
675	
676	/** Reverse a suspend: re-enable the site, rebuild the FPM pool, unlock the user. */
677	async function taskUnsuspend(conn: Client, a: LifecycleAccount): Promise<void> {
678	  assertLifecycleSafe(a);
679	  const { home, webroot } = accountPaths(a.username);
680	  await writeFpmPool(conn, a.username, home, webroot, a.phpVersion);
681	  await run(conn, "unsuspend: enable vhost", `ln -sfn /etc/nginx/sites-available/hosting-${a.username}.conf /etc/nginx/sites-enabled/hosting-${a.username}.conf; nginx -t && systemctl reload nginx || true`);
682	  await run(conn, "unsuspend: unlock user", `usermod -U ${a.username} 2>/dev/null || true`);
683	}
684	
685	/** Fully deprovision: remove the vhost + FPM pool, delete the jailed user and its
686	 *  home, and drop every database AND db-user scoped to this account (`<user>_*`). */
687	async function taskTerminate(conn: Client, a: LifecycleAccount): Promise<void> {
688	  assertLifecycleSafe(a);
689	  await run(conn, "terminate: remove vhost", `rm -f /etc/nginx/sites-enabled/hosting-${a.username}.conf /etc/nginx/sites-available/hosting-${a.username}.conf; systemctl reload nginx 2>/dev/null || true`);
690	  await run(conn, "terminate: remove fpm pool", `rm -f /etc/php/${a.phpVersion}/fpm/pool.d/${a.username}.conf; systemctl reload php${a.phpVersion}-fpm 2>/dev/null || true`);
691	  // Drop this account's scoped databases (`<user>_*`) AND the matching db-users
692	  // (named `<user>_<slug>` / `<user>_wp`, NOT bare `<user>` — audit MEDIUM-2).
693	  await run(conn, "terminate: drop scoped dbs + users", `for d in $(mysql -N -e "SHOW DATABASES LIKE '${a.username}\\_%'" 2>/dev/null); do mysql -e "DROP DATABASE \\\`$d\\\`" 2>/dev/null; done; for u in $(mysql -N -e "SELECT User FROM mysql.user WHERE User LIKE '${a.username}\\_%'" 2>/dev/null); do mysql -e "DROP USER IF EXISTS '$u'@'localhost'" 2>/dev/null; done; true`);
694	  await run(conn, "terminate: delete user + home", `pkill -u ${a.username} 2>/dev/null; sleep 1; userdel -r ${a.username} 2>/dev/null || true`);
695	}
