707	async function taskWordpressInstall(conn: Client, a: { id: string; username: string; primaryDomain: string; maxDatabases: number }, payload: string | null): Promise<string> {
708	  await assertDbCap(a.id, a.maxDatabases);
709	  const p = JSON.parse(payload || "{}") as { dbName?: string; dbUser?: string; dbPassEnc?: string; adminUser?: string; adminPassEnc?: string; adminEmail?: string };
710	  const dbName = String(p.dbName ?? "");
711	  const dbUser = String(p.dbUser ?? "");
712	  const dbPass = (p.dbPassEnc ? decryptSecret(p.dbPassEnc) : "") ?? "";
713	  const adminUser = String(p.adminUser ?? "");
714	  const adminPass = (p.adminPassEnc ? decryptSecret(p.adminPassEnc) : "") ?? "";
715	  const adminEmail = String(p.adminEmail ?? "");
716	  if (!SAFE_ID.test(dbName) || !SAFE_ID.test(dbUser.slice(0, 32)) || !dbPass) throw new Error("invalid db identifiers");
717	  if (!/^[A-Za-z0-9_]{1,32}$/.test(adminUser) || !/^[A-Za-z0-9]{8,64}$/.test(adminPass) || !SAFE_EMAIL.test(adminEmail)) throw new Error("invalid admin identifiers");
718	  const u = a.username;
719	  const d = a.primaryDomain;
720	  if (!isValidUnixUsername(u) || !isValidHostingDomain(d)) throw new Error("unsafe account");
721	  const { webroot } = accountPaths(u);
722	
723	  await run(conn, "wp-cli", `command -v wp >/dev/null 2>&1 || (curl -fsSL https://raw.githubusercontent.com/wp-cli/builds/gh-pages/phar/wp-cli.phar -o /usr/local/bin/wp && chmod +x /usr/local/bin/wp)`);
724	  const sql = sqlForMysqlExec(buildScopedGrantSql(dbName, dbUser, dbPass));
725	  await run(conn, "wp db", `mysql -e "${sql}"`);
726	  const wp = `sudo -u ${u} -H wp --path=${webroot}`;
727	  await run(conn, "wp download", `${wp} core download --force`);
728	  await run(conn, "wp config", `${wp} config create --dbname=${dbName} --dbuser=${dbUser} --dbpass='${dbPass}' --force`);
729	  await run(conn, "wp install", `${wp} core install --url='https://${d}' --title='${d}' --admin_user='${adminUser}' --admin_password='${adminPass}' --admin_email='${adminEmail}' --skip-email`);
730	  await db.hostingDatabase.create({ data: { accountId: a.id, name: dbName, dbUser, passwordEnc: null, status: "ACTIVE" } }).catch(() => undefined);
731	  // Shown ONCE in the panel, then the task result is cleared.
732	  return JSON.stringify({ adminUser, adminPassword: adminPass, url: `https://${d}/wp-admin/` });
733	}
