755	async function taskAppInstall(conn: Client, a: { id: string; username: string; primaryDomain: string; maxDatabases: number }, payload: string | null): Promise<string> {
756	  const p = JSON.parse(payload || "{}") as { slug?: string; dbName?: string; dbUser?: string; dbPassEnc?: string };
757	  const slug = String(p.slug ?? "");
758	  const recipe = APP_RECIPES[slug];
759	  if (!recipe) throw new Error("unknown app");
760	  if (recipe.needsDb) await assertDbCap(a.id, a.maxDatabases);
761	  const u = a.username;
762	  if (!isValidUnixUsername(u)) throw new Error("unsafe account");
763	  const { webroot } = accountPaths(u);
764	  const isBz2 = recipe.url.endsWith(".bz2");
765	  const tarFlags = `${isBz2 ? "xjf" : "xzf"} - ${recipe.strip ? `--strip-components=${recipe.strip}` : ""}`;
766	  // Download + extract into the webroot AS the account user (jailed).
767	  await run(conn, `download ${slug}`, `sudo -u ${u} -H bash -c "cd ${webroot} && curl -fsSL '${recipe.url}' | tar ${tarFlags}"`);
768	  let dbInfo = "";
769	  if (recipe.needsDb) {
770	    const dbName = String(p.dbName ?? "");
771	    const dbUser = String(p.dbUser ?? "");
772	    const dbPass = (p.dbPassEnc ? decryptSecret(p.dbPassEnc) : "") ?? "";
773	    if (!/^[a-z0-9_]{1,64}$/.test(dbName) || !/^[a-z0-9_]{1,32}$/.test(dbUser) || !dbPass) throw new Error("invalid db identifiers");
774	    const sql = sqlForMysqlExec(buildScopedGrantSql(dbName, dbUser, dbPass));
775	    await run(conn, "app db", `mysql -e "${sql}"`);
776	    await db.hostingDatabase.create({ data: { accountId: a.id, name: dbName, dbUser, passwordEnc: null, status: "ACTIVE" } }).catch(() => undefined);
777	    dbInfo = ` Database: ${dbName} · user ${dbUser} · password ${dbPass} (host localhost).`;
778	  }
779	  return JSON.stringify({ app: recipe.name, url: `https://${a.primaryDomain}/`, note: recipe.note + dbInfo });
780	}
