782	/** Archive the account's home + DB dumps to a node-local backups dir.
783	 *
784	 * SECURITY (audit 2026-08-01, cross-tenant DB compromise): the DB dumps are
785	 * written to a ROOT-ONLY directory OUTSIDE the tenant's chroot and are NEVER
786	 * chowned to the tenant. The old code dumped into ${home}/.dbdump and chowned it
787	 * to the account user, so the tenant — who holds live SFTP creds chrooted to
788	 * ${home} — could race in and overwrite <db>.sql with arbitrary SQL that restore
789	 * later piped into `mysql` as root (a shared-node-wide GRANT/USE). Keeping the
790	 * dumps root-owned and off the tenant tree means the archived SQL is always our
791	 * own mysqldump output, never tenant-controlled. */
792	async function taskBackup(conn: Client, a: { id: string; username: string }, tsLabel: string): Promise<void> {
793	  const u = a.username;
794	  const dir = `/var/hosting-backups/${u}`;
795	  const dumpDir = `${dir}/dbdump`;
796	  const path = `${dir}/${tsLabel}.tar.gz`;
797	  // Root-only staging for the DB dumps; the whole dir is 700 root:root so the
798	  // tenant can neither read nor tamper with it.
799	  await run(
800	    conn,
801	    "dump dbs",
802	    `rm -rf ${dumpDir}; mkdir -p ${dumpDir}; chown -R root:root ${dir}; chmod 700 ${dir} ${dumpDir}; ` +
803	      `for dbn in $(mysql -N -e "SHOW DATABASES LIKE '${u}\\_%'" 2>/dev/null); do mysqldump "$dbn" > ${dumpDir}/"$dbn".sql 2>/dev/null; done`,
804	  );
805	  // One archive holding the home tree (${u}/…) and the root-owned dumps (dbdump/…).
806	  await run(conn, "tar home", `tar -czf ${path} -C /home ${u} -C ${dir} dbdump && rm -rf ${dumpDir}`);
807	  const st = await exec(conn, `stat -c %s ${path} 2>/dev/null || echo 0`);
808	  const sizeBytes = Math.max(0, Math.min(2_000_000_000, Number(st.out.trim()) || 0));
809	  await db.hostingBackup.create({ data: { accountId: a.id, path, sizeBytes } });
810	  // Retain the newest 5 per account; delete older files + rows.
811	  const all = await db.hostingBackup.findMany({ where: { accountId: a.id }, orderBy: { createdAt: "desc" } });
812	  for (const old of all.slice(5)) {
813	    await exec(conn, `rm -f ${old.path}`).catch(() => undefined);
814	    await db.hostingBackup.delete({ where: { id: old.id } }).catch(() => undefined);
815	  }
816	}
