837	  // shell `case` guard is belt-and-braces on top of the glob — a dump for
838	  // another tenant's DB is never fed to mysql.
839	  await run(
840	    conn,
841	    "restore dbs",
842	    `for f in ${stage}/dbdump/${u}_*.sql; do [ -f "$f" ] || continue; bn=$(basename "$f" .sql); ` +
843	      `case "$bn" in ${u}_*) mysql "$bn" < "$f" 2>/dev/null;; esac; done`,
844	  );
845	  // Re-assert the hardened perms the restored tree may have flattened: webroot
846	  // stays <user>:www-data setgid (nginx reads via group, peers don't), tmp private.
