35	/** Least-loaded enabled+online node with account headroom. */
36	async function scheduleHostingNode(): Promise<{ id: string } | null> {
37	  const nodes = await db.hostingNode.findMany({ where: { enabled: true, status: "ONLINE" } });
38	  if (!nodes.length) return null;
39	  const loads = await Promise.all(
40	    nodes.map(async (n) => ({
41	      node: n,
42	      used: await db.hostingAccount.count({ where: { hostingNodeId: n.id, status: { in: [...LIVE_STATES] } } }),
43	    })),
44	  );
45	  const withRoom = loads.filter((l) => l.used < l.node.maxAccounts).sort((a, b) => a.used - b.used);
46	  return withRoom.length ? { id: withRoom[0].node.id } : null;
47	}
