60	/**
61	 * Order a shared-hosting account for a domain on a plan. Same purchase discipline
62	 * as every other paid path: no spending while impersonating, verified email,
63	 * wallet charge in the same tx that creates the record. The account starts
64	 * PENDING; the worker provisioner brings it up (inert until shared hosting is
65	 * enabled — see worker/hosting.ts).
66	 */
67	export async function orderHostingAccount(planId: string, domain: string): Promise<HostingResult> {
68	  const user = await requireUser();
69	  await assertNotImpersonating();
70	  const unverified = await emailVerificationError(user);
71	  if (unverified) return { error: unverified };
72	
73	  const name = normalizeHostingDomain(domain);
74	  if (!name) return { error: "Enter a domain." };
75	  if (!isValidHostingDomain(name)) return { error: "Enter a valid domain (e.g. example.com)." };
76	
77	  const plan = await db.hostingPlan.findUnique({ where: { id: planId } });
78	  if (!plan || !plan.active) return { error: "That hosting plan isn’t available." };
79	
80	  // One account per domain across ALL customers — same cross-tenant guard as
81	  // email subscriptions (a shared vhost keys on server_name).
82	  const dupe = await db.hostingAccount.findFirst({ where: { primaryDomain: name, status: { in: [...LIVE_STATES] } } });
83	  if (dupe) {
84	    return {
85	      error:
86	        dupe.userId === user.id
87	          ? "You already have a hosting account for this domain."
88	          : "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across.",
89	    };
90	  }
91	  // Also reject if this hostname is already someone's subdomain or addon domain
92	  // (audit HIGH-2: the primary-order guard used to ignore those two tables).
93	  if (await isHostnameClaimed(name)) {
94	    return { error: "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across." };
95	  }
96	
97	  const node = await scheduleHostingNode();
98	  if (!node) return { error: "No shared-hosting capacity is available right now — please try again shortly." };
99	
100	  const promo = currentPromo(new Date());
101	  const chargeCents = promoPriceCents(plan.priceCents, promo);
102	  const promoNote = promo.discountPercent > 0 ? ` — ${promo.name} ${promo.discountPercent}% off first term` : "";
103	  if (user.balanceCents < chargeCents) return { error: "Insufficient balance. Top up your wallet first." };
104	
105	  const limits = planLimits(plan);
106	  const username = await pickUsername(node.id, user.email.split("@")[0] ?? "acct");
107	
108	  let accountId = "";
109	  try {
110	    await db.$transaction(async (tx) => {
111	      await debitWallet(tx, user.id, chargeCents);
112	      await tx.walletTransaction.create({
113	        data: { userId: user.id, amountCents: -chargeCents, description: `Web Hosting: ${plan.name} for ${name}${promoNote}` },
114	      });
115	      const acct = await tx.hostingAccount.create({
116	        data: {
117	          userId: user.id,
118	          hostingNodeId: node.id,
119	          planId: plan.id,
120	          username,
121	          primaryDomain: name,
122	          status: "PENDING",
123	          diskQuotaMB: limits.diskGB * 1024,
124	          maxSites: limits.maxSites,
125	          maxDatabases: limits.maxDatabases,
126	          expiresAt: addMonths(new Date(), 1),
127	        },
128	      });
129	      accountId = acct.id;
130	    });
131	  } catch (e) {
132	    return { error: "Couldn’t place the order. Your wallet was not charged — try again." };
133	  }
134	
135	  await db.auditLog.create({ data: { userId: user.id, action: "hosting.order", detail: `${plan.name} · ${name}` } }).catch(() => {});
136	  revalidatePath("/dashboard/hosting");
137	  return { ok: true, accountId };
138	}
