461	// ---------- Subdomains + addon domains + cron (cPanel-class site mgmt) -------
462	// Every value that reaches the node shell is validated here (isValidUnixUsername
463	// / isValidHostingDomain / isValidSubdomainLabel / cron validators) AND re-checked
464	// in the worker. Caps are enforced inside a Serializable transaction so concurrent
465	// creates cannot both read a stale count and blow past the plan (same discipline
466	// as createHostingDatabase). The task is queued in the SAME tx as the row create.
467	
468	const SITE_STATES = ["PENDING", "ACTIVE"] as const;
469	const MAX_CRON_JOBS = 20;
