471	/** Owner (or admin) + ACTIVE account, returning the fields the site actions need. */
472	async function ownedSiteAccount(id: string) {
473	  const user = await requireUser();
474	  // Impersonating admins must not create/destroy customer resources — cron is
475	  // arbitrary command execution as the customer's unix user; subdomains/addons
476	  // mint live vhosts. Matches createHostingAccount/createHostingDatabase (audit MED-3).
477	  await assertNotImpersonating();
478	  const a = await db.hostingAccount.findUnique({
479	    where: { id },
480	    select: { id: true, userId: true, status: true, username: true, primaryDomain: true, maxSites: true },
481	  });
482	  if (!a) return { error: "Account not found." as const };
483	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." as const };
484	  if (a.status !== "ACTIVE") return { error: "The account is still being set up." as const };
485	  return { user, a };
486	}
