488	/**
489	 * Is this hostname already claimed ANYWHERE? A shared node routes purely by nginx
490	 * `server_name`, and a hostname can live in THREE places — a primary domain, a
491	 * subdomain, or an addon domain. Before this, each creator only checked its own
492	 * table, so an addon could shadow a victim's subdomain (or vice-versa) on a
493	 * co-located node = cross-tenant vhost takeover (security audit HIGH-1/HIGH-2).
494	 * This single check, used by all three creators, is the app-level invariant (no DB
495	 * unique can span three tables + a deliberately re-usable primaryDomain).
496	 */
497	async function isHostnameClaimed(name: string): Promise<boolean> {
498	  const [prim, sub, addon] = await Promise.all([
499	    db.hostingAccount.count({ where: { primaryDomain: name, status: { in: [...LIVE_STATES] } } }),
500	    db.hostingSubdomain.count({ where: { fqdn: name, status: { in: [...SITE_STATES] } } }),
501	    db.hostingAddonDomain.count({ where: { domain: name, status: { in: [...SITE_STATES] } } }),
502	  ]);
503	  return prim + sub + addon > 0;
504	}
