542	export async function createSubdomain(accountId: string, label: string): Promise<HostingResult> {
543	  const ctx = await ownedSiteAccount(accountId);
544	  if ("error" in ctx) return { error: ctx.error };
545	  const { a } = ctx;
546	  const clean = String(label ?? "").trim().toLowerCase();
547	  if (!isValidSubdomainLabel(clean)) return { error: "Enter a valid subdomain label — letters, digits and hyphens only." };
548	  const fqdn = `${clean}.${a.primaryDomain}`;
549	  if (!isValidHostingDomain(fqdn)) return { error: "That subdomain isn’t a valid hostname." };
550	  // Reject if another tenant already claimed this exact hostname as an addon domain
551	  // (or primary). fqdn @unique blocks subdomain↔subdomain; this closes the addon
552	  // path (audit HIGH-1, reverse direction).
553	  if (await isHostnameClaimed(fqdn)) {
554	    return { error: "That hostname is already in use on Nxeon." };
555	  }
556	  const { docroot } = subdomainPaths(a.username, clean);
557	  try {
558	    await db.$transaction(async (tx) => {
559	      const subs = await tx.hostingSubdomain.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
560	      const addons = await tx.hostingAddonDomain.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
561	      if (subs + addons >= a.maxSites) throw new Error("CAP");
562	      const sub = await tx.hostingSubdomain.create({ data: { accountId: a.id, label: clean, fqdn, docroot, status: "PENDING" } });
563	      await tx.hostingTask.create({ data: { accountId: a.id, kind: "CREATE_SUBDOMAIN", payload: JSON.stringify({ subdomainId: sub.id }) } });
564	    }, { isolationLevel: "Serializable" });
565	  } catch (e) {
566	    if (e instanceof Error && e.message === "CAP") return { error: siteCapMessage(a.maxSites) };
567	    return { error: "That subdomain already exists, or the request raced — try again." };
568	  }
569	  revalidatePath(`/dashboard/hosting/${accountId}`);
570	  return { ok: true };
571	}
