584	export async function createAddonDomain(accountId: string, domain: string): Promise<HostingResult> {
585	  const ctx = await ownedSiteAccount(accountId);
586	  if ("error" in ctx) return { error: ctx.error };
587	  const { a } = ctx;
588	  const name = normalizeHostingDomain(domain);
589	  if (!name || !isValidHostingDomain(name)) return { error: "Enter a valid domain (e.g. example.com)." };
590	  if (name === a.primaryDomain) return { error: "That’s already your primary domain." };
591	  // Cross-tenant uniqueness across ALL three hostname tables — a shared vhost keys
592	  // on server_name, so an addon must not shadow anyone's primary, subdomain, or
593	  // addon (audit HIGH-1: this used to omit HostingSubdomain.fqdn).
594	  if (await isHostnameClaimed(name)) {
595	    return { error: "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across." };
596	  }
597	  const { docroot } = addonDomainPaths(a.username, name);
598	  try {
599	    await db.$transaction(async (tx) => {
600	      const subs = await tx.hostingSubdomain.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
601	      const addons = await tx.hostingAddonDomain.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
602	      if (subs + addons >= a.maxSites) throw new Error("CAP");
603	      const addon = await tx.hostingAddonDomain.create({ data: { accountId: a.id, domain: name, docroot, status: "PENDING" } });
604	      await tx.hostingTask.create({ data: { accountId: a.id, kind: "CREATE_ADDON_DOMAIN", payload: JSON.stringify({ addonId: addon.id }) } });
605	    }, { isolationLevel: "Serializable" });
606	  } catch (e) {
607	    if (e instanceof Error && e.message === "CAP") return { error: siteCapMessage(a.maxSites) };
608	    return { error: "That domain is already added, or the request raced — try again." };
609	  }
610	  revalidatePath(`/dashboard/hosting/${accountId}`);
611	  return { ok: true };
612	}
