625	export async function createCron(accountId: string, schedule: string, command: string): Promise<HostingResult> {
626	  const ctx = await ownedSiteAccount(accountId);
627	  if ("error" in ctx) return { error: ctx.error };
628	  const { a } = ctx;
629	  const sched = String(schedule ?? "").trim();
630	  const cmd = String(command ?? "").trim();
631	  if (!isValidCronSchedule(sched)) return { error: "Enter a valid 5-field cron schedule (e.g. 0 3 * * *)." };
632	  if (!isValidCronCommand(cmd)) return { error: "Enter a command (one line, up to 500 characters, no % character)." };
633	  try {
634	    await db.$transaction(async (tx) => {
635	      const n = await tx.hostingCron.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
636	      if (n >= MAX_CRON_JOBS) throw new Error("CAP");
637	      const cron = await tx.hostingCron.create({ data: { accountId: a.id, schedule: sched, command: cmd, status: "PENDING" } });
638	      await tx.hostingTask.create({ data: { accountId: a.id, kind: "CREATE_CRON", payload: JSON.stringify({ cronId: cron.id }) } });
639	    }, { isolationLevel: "Serializable" });
640	  } catch (e) {
641	    if (e instanceof Error && e.message === "CAP") return { error: `You can schedule up to ${MAX_CRON_JOBS} cron jobs.` };
642	    return { error: "Couldn’t add the cron job — try again." };
643	  }
644	  revalidatePath(`/dashboard/hosting/${accountId}`);
645	  return { ok: true };
646	}
