940	/** (Re)write the account user's crontab from its ACTIVE cron rows. Runs `crontab
941	 *  -u <user>` so every command runs AS the jailed user (confined). The whole
942	 *  crontab is rebuilt each time (idempotent); a quoted heredoc prevents any shell
943	 *  expansion, and each line is re-validated so nothing unsafe is ever written. */
944	async function writeUserCrontab(conn: Client, username: string, accountId: string): Promise<void> {
945	  if (!isValidUnixUsername(username)) throw new Error("unsafe account username");
946	  const crons = await db.hostingCron.findMany({ where: { accountId, status: "ACTIVE" }, orderBy: { createdAt: "asc" } });
947	  const lines = crons
948	    .filter((c) => isValidCronSchedule(c.schedule) && isValidCronCommand(c.command))
949	    .map((c) => `${c.schedule} ${c.command}`);
950	  if (lines.length === 0) {
951	    await run(conn, "clear crontab", `crontab -u ${username} -r 2>/dev/null || true`);
952	    return;
953	  }
954	  const body = lines.join("\n") + "\n";
955	  await run(conn, "write crontab", `crontab -u ${username} - <<'NXCRONEOF'\n${body}NXCRONEOF`);
956	}
