242	/**
243	 * DNS→HTTPS stepper driven by the REAL serve-verification the worker records
244	 * (serveHttpOk / serveHttpsOk / sslActive), so it can never claim "live" while
245	 * HTTPS actually refuses. Three overall states, per the account's measured health:
246	 *   • verified — a trusted cert is live (sslActive) and 443 answers → "HTTPS live ✓"
247	 *   • issuing  — the site answers (self-signed 443 or HTTP) but no trusted cert yet
248	 *   • dns      — nothing answers for the domain yet (DNS not pointed at us)
249	 */
250	function DnsStepper({ account }: { account: HostingAccountView }) {
251	  const checked = account.healthCheckedAt != null || account.serveHttpOk != null;
252	  const serving = account.serveHttpOk === true || account.serveHttpsOk === true;
253	  const verified = account.sslActive && account.serveHttpsOk !== false;
254	  const state: "verified" | "issuing" | "dns" | "pending" =
255	    verified ? "verified" : serving ? "issuing" : checked ? "dns" : "pending";
256	
257	  const steps = [
258	    { label: "Point domain", done: true, hint: "Add the A record above" },
259	    {
260	      label: "Site live",
261	      done: state === "issuing" || state === "verified",
262	      hint: state === "issuing" || state === "verified" ? "Serving traffic" : state === "dns" ? "DNS not detected yet" : "Checking…",
263	    },
264	    {
265	      label: "HTTPS verified",
266	      done: state === "verified",
267	      hint: state === "verified" ? "Certificate trusted" : state === "issuing" ? "Issuing certificate" : "Auto after DNS",
268	    },
269	  ];
270	
271	  const headline =
272	    account.healthNote ??
273	    (state === "verified" ? "HTTPS live — verified" : state === "issuing" ? "HTTP live, HTTPS issuing" : state === "dns" ? "DNS not detected yet" : "Not checked yet");
274	  const headlineTone = state === "verified" ? "text-emerald-300" : state === "dns" ? "text-slate-400" : "text-amber-300";
275	
276	  return (
277	    <div className="mt-4">
278	      <div className="flex items-center">
279	        {steps.map((s, i) => (
280	          <div key={s.label} className="flex flex-1 items-center last:flex-none">
281	            <div className="flex flex-col items-center">
282	              <span className={`flex h-6 w-6 items-center justify-center rounded-full border text-[11px] ${s.done ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-300" : "border-amber-500/40 bg-amber-500/10 text-amber-300"}`}>
283	                {s.done ? "✓" : i + 1}
284	              </span>
285	            </div>
286	            {i < steps.length - 1 && <div className={`mx-2 h-px flex-1 ${steps[i + 1].done ? "bg-emerald-500/40" : "bg-white/10"}`} />}
287	          </div>
288	        ))}
289	      </div>
290	      <div className="mt-1.5 flex items-start justify-between text-[11px]">
291	        {steps.map((s) => (
292	          <div key={s.label} className="flex-1 text-center first:text-left last:text-right">
293	            <p className={s.done ? "text-emerald-300" : "text-slate-400"}>{s.label}</p>
294	            <p className="text-slate-500">{s.hint}</p>
295	          </div>
296	        ))}
297	      </div>
298	      <p className={`mt-3 text-xs font-medium ${headlineTone}`}>
299	        {headline}
300	        {account.healthCheckedAt && (
301	          <span className="ml-1 font-normal text-slate-500">· checked {new Date(account.healthCheckedAt).toLocaleTimeString()}</span>
302	        )}
303	      </p>
304	      {state !== "verified" && (
305	        <p className="mt-1 text-xs text-slate-500">
306	          A trusted HTTPS certificate is issued automatically once your domain resolves to us — this can take a few minutes after you set the DNS record. Use <span className="text-slate-300">Go live</span> to check right away.
307	        </p>
308	      )}
309	    </div>
310	  );
311	}
