11	  const [entries, setEntries] = useState<FsEntryView[]>([]);
12	  const [err, setErr] = useState("");
13	  const [busy, setBusy] = useState(false);
14	  const [loaded, setLoaded] = useState(false);
15	  const fileRef = useRef<HTMLInputElement>(null);
16	
17	  async function load(p: string) {
18	    setBusy(true); setErr("");
19	    const r = await hostingListFiles(accountId, p);
20	    setBusy(false); setLoaded(true);
21	    if (r.error) setErr(r.error); else { setEntries(r.entries ?? []); setPath(r.path ?? p); }
22	  }
23	  useEffect(() => { if (open) load(path); /* eslint-disable-next-line */ }, [open]);
24	
25	  const parent = () => { const parts = path.split("/").filter(Boolean); parts.pop(); load(parts.join("/") || "public_html"); };
26	  async function upload(files: FileList | null) {
27	    if (!files?.length) return;
28	    setBusy(true);
29	    for (const f of Array.from(files)) {
30	      const fd = new FormData(); fd.append("file", f);
31	      await fetch(`/api/hosting/files?accountId=${accountId}&path=${encodeURIComponent(path)}`, { method: "POST", body: fd }).catch(() => {});
32	    }
33	    if (fileRef.current) fileRef.current.value = "";
34	    load(path);
35	  }
36	
37	  if (!open) return <button className="text-xs font-medium text-brand-300 hover:underline" onClick={() => setOpen(true)}>Open file manager</button>;
38	  return (
