44	          <input ref={fileRef} type="file" multiple className="hidden" onChange={(e) => upload(e.target.files)} />
45	          <button className="text-slate-400 hover:underline" onClick={async () => { const n = prompt("New folder name"); if (n) { const r = await hostingMkdir(accountId, path, n); if (r.error) alert(r.error); else load(path); } }}>New folder</button>
46	          <button className="text-slate-500 hover:underline" onClick={() => setOpen(false)}>close</button>
47	        </div>
48	      </div>
49	      {err && <p className="text-xs text-amber-300">{err}</p>}
50	      {busy && <p className="text-xs text-slate-500">Loading…</p>}
51	      {loaded && !busy && !err && entries.length === 0 && path === "public_html" && (
52	        <p className="px-1 py-2 text-xs text-slate-500">This folder is empty. Upload your site files here, or install an app.</p>
53	      )}
54	      <ul className="max-h-56 overflow-auto text-xs">
55	        {path !== "public_html" && path !== "" && (
56	          <li><button className="text-slate-400 hover:underline" onClick={parent}>⬆ ..</button></li>
57	        )}
58	        {entries.map((e) => (
59	          <li key={e.name} className="flex items-center justify-between py-0.5">
60	            {e.isDir ? (
61	              <button className="text-brand-200 hover:underline" onClick={() => load(`${path}/${e.name}`)}>📁 {e.name}</button>
62	            ) : (
63	              <a className="text-slate-300 hover:underline" href={`/api/hosting/files?accountId=${accountId}&path=${encodeURIComponent(`${path}/${e.name}`)}`}>📄 {e.name}</a>
64	            )}
65	            <span className="flex items-center gap-2 text-slate-500">
66	              {!e.isDir && <span>{(e.size / 1024).toFixed(0)} KB</span>}
67	              <button className="text-red-400 hover:underline" onClick={async () => { if (confirm(`Delete ${e.name}?`)) { const r = await hostingDeleteFile(accountId, `${path}/${e.name}`, e.isDir); if (r.error) alert(r.error); else load(path); } }}>del</button>
68	            </span>
69	          </li>
70	        ))}
71	      </ul>
72	    </div>
73	  );
74	}
