7	const MAX_UPLOAD = 100 * 1024 * 1024;
8	
9	async function ownedNode(accountId: string) {
10	  const user = await requireUser();
11	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, include: { node: true } });
12	  if (!a) return null;
13	  if (a.userId !== user.id && user.role !== "ADMIN") return null;
14	  if (a.status !== "ACTIVE") return null;
15	  return a;
16	}
