18	/** Upload a file into the account webroot (jailed). ?accountId=&path= */
19	export async function POST(req: NextRequest) {
20	  const a = await ownedNode(req.nextUrl.searchParams.get("accountId") ?? "");
21	  if (!a) return NextResponse.json({ error: "Forbidden" }, { status: 403 });
22	  const dir = req.nextUrl.searchParams.get("path") ?? "public_html";
23	  const form = await req.formData();
24	  const file = form.get("file");
25	  if (!(file instanceof File)) return NextResponse.json({ error: "No file" }, { status: 400 });
26	  if (file.size > MAX_UPLOAD) return NextResponse.json({ error: "File too large (max 100 MB)" }, { status: 413 });
27	  const safeName = file.name.replace(/[^A-Za-z0-9._-]/g, "_").slice(0, 120);
28	  if (SANDBOX) return NextResponse.json({ ok: true });
29	  const t = fsTargetFor(a);
30	  if (!t) return NextResponse.json({ error: "File manager not ready" }, { status: 409 });
31	  try {
32	    await fsWriteBuffer(t, `${dir}/${safeName}`, Buffer.from(await file.arrayBuffer()));
33	    return NextResponse.json({ ok: true, name: safeName });
34	  } catch {
35	    return NextResponse.json({ error: "Upload failed" }, { status: 500 });
36	  }
37	}
38	
39	/** Download a file from the account (jailed). ?accountId=&path= */
40	export async function GET(req: NextRequest) {
41	  const a = await ownedNode(req.nextUrl.searchParams.get("accountId") ?? "");
42	  if (!a) return new NextResponse("Forbidden", { status: 403 });
43	  const path = req.nextUrl.searchParams.get("path") ?? "";
44	  if (SANDBOX) return new NextResponse("sandbox", { status: 200 });
45	  const t = fsTargetFor(a);
46	  if (!t) return new NextResponse("Not ready", { status: 409 });
47	  try {
48	    const buf = await fsReadBuffer(t, path);
49	    const name = path.split("/").pop() ?? "download";
50	    return new NextResponse(new Uint8Array(buf), { status: 200, headers: { "Content-Type": "application/octet-stream", "Content-Disposition": `attachment; filename="${name.replace(/"/g, "")}"` } });
51	  } catch {
52	    return new NextResponse("Not found", { status: 404 });
53	  }
54	}
