 * customer's databases only, '<user>'@'localhost'). So even if the randomized URL
 * leaks: (1) the visitor still needs a valid DB username+password, which only the
 * tenant knows; (2) MySQL only accepts those creds from localhost — Adminer runs
 * inside the tenant's own FPM pool on the node, so the connection is localhost;
 * (3) the grants confine that user to its own databases, so there is no lateral
 * path to a neighbour's data. The file is downloaded AS the jailed account user
 * (never root), so it lands owned by the tenant inside their chroot.
 */
async function taskInstallDbTool(conn: Client, a: { id: string; username: string }, payload: string | null): Promise<string> {
  const u = a.username;
  if (!isValidUnixUsername(u)) throw new Error("unsafe account username");
  const p = JSON.parse(payload || "{}") as { token?: string; path?: string };
  const token = String(p.token ?? "");
  if (!isValidDbToolToken(token)) throw new Error("invalid db-tool token");
  const { webroot } = accountPaths(u);
  const dir = `nxtools-${token}`;
  const urlPath = `/${dir}/adminer.php`;
  // Download the single Adminer file into the account webroot AS the jailed user.
  await run(
    conn,
    "install adminer",
    `sudo -u ${u} -H bash -c "mkdir -p ${webroot}/${dir} && curl -fsSL '${ADMINER_URL}' -o ${webroot}/${dir}/adminer.php"`,
  );
  await db.hostingAccount.update({ where: { id: a.id }, data: { dbToolPath: urlPath } });
  return JSON.stringify({ url: urlPath });
}

/**
 * Re-apply an account's snapshotted plan limits on the node after a plan upgrade:
 * raise the disk quota with the new block count (soft = 95% of hard), and rewrite
 * the FPM pool. Reads the already-updated snapshot on the account row (the action
 * writes diskQuotaMB before queuing this), so it is idempotent + safe to re-run.
 * Both shell-bound values are re-validated here, same discipline as the lifecycle
 * tasks. Content task → runs ACTIVE-only.
 */
async function taskApplyPlanLimits(conn: Client, a: { id: string; username: string; phpVersion: string; diskQuotaMB: number }): Promise<void> {
  const u = a.username;
  if (!isValidUnixUsername(u)) throw new Error("unsafe account username");
  if (!/^\d\.\d$/.test(a.phpVersion)) throw new Error("unsafe php version");
  const { home, webroot } = accountPaths(u);
  const hardBlocks = diskQuotaBlocks(Math.max(1, Math.round(a.diskQuotaMB / 1024)));
  const softBlocks = Math.floor(hardBlocks * 0.95);
  await run(conn, "raise disk quota", `command -v setquota >/dev/null 2>&1 && setquota -u ${u} ${softBlocks} ${hardBlocks} 0 0 /home || echo 'quota tool absent — skipped'`);
  await writeFpmPool(conn, u, home, webroot, a.phpVersion);
}

