export async function installDbTool(accountId: string): Promise<{ ok?: boolean; error?: string; url?: string }> {
  const user = await requireUser();
  await assertNotImpersonating();
  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { id: true, userId: true, status: true, dbToolPath: true } });
