"use client";

import { useEffect, useState } from "react";
import { listHostingUpgradePlans, upgradeHostingPlan, type UpgradePlanView } from "@/lib/actions-hosting";

function money(cents: number): string {
  return `$${(cents / 100).toFixed(2)}`;
}

/**
 * Plan picker for upgrading a hosting account. Lists the larger plans the account
 * may move UP to (from listHostingUpgradePlans) with the exact price delta charged
 * now, and confirms before charging the wallet via upgradeHostingPlan. Up-only —
 * the server re-checks and never downgrades.
 */
export function PlanUpgrade({ accountId }: { accountId: string }) {
  const [plans, setPlans] = useState<UpgradePlanView[] | null>(null);
  const [busyId, setBusyId] = useState<string | null>(null);
  const [err, setErr] = useState("");
  const [done, setDone] = useState(false);

  useEffect(() => {
    listHostingUpgradePlans(accountId).then((r) => { if (!r.error) setPlans(r.plans ?? []); else setPlans([]); }).catch(() => setPlans([]));
  }, [accountId]);

  async function upgrade(p: UpgradePlanView) {
    if (!window.confirm(`Upgrade to ${p.name}? Your wallet will be charged ${money(p.deltaCents)} now (the price difference for this term).`)) return;
    setBusyId(p.id); setErr("");
    const res = await upgradeHostingPlan(accountId, p.id);
    setBusyId(null);
    if (res.error) { setErr(res.error); return; }
    setDone(true);
    // Reflect the new plan across the page.
    setTimeout(() => window.location.reload(), 900);
  }

  if (plans === null) return <p className="text-xs text-slate-500">Loading upgrade options…</p>;
  if (done) return <p className="text-sm text-emerald-300">Plan upgraded — applying the new limits…</p>;
  if (plans.length === 0) return <p className="text-xs text-slate-500">You’re on our largest plan. Nothing bigger to move up to.</p>;

  return (
    <div>
      <p className="mb-3 text-sm font-medium text-slate-300">Upgrade your plan</p>
      <p className="mb-3 text-xs text-slate-500">
        Move up to a larger plan instantly. You’re charged only the price difference for the current term; your renewal date doesn’t change.
      </p>
      <div className="space-y-2">
        {plans.map((p) => (
          <div key={p.id} className="flex flex-wrap items-center justify-between gap-3 rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2">
            <div className="min-w-0">
              <p className="text-sm font-medium text-slate-200">{p.name}</p>
              <p className="text-xs text-slate-500">
                {p.diskGB} GB · {p.maxSites} site{p.maxSites === 1 ? "" : "s"} · {p.maxDatabases} database{p.maxDatabases === 1 ? "" : "s"}
                {p.tagline ? ` · ${p.tagline}` : ""}
              </p>
            </div>
            <button
              type="button"
              className="btn-secondary whitespace-nowrap text-xs"
              disabled={busyId !== null}
              onClick={() => upgrade(p)}
            >
              {busyId === p.id ? "Upgrading…" : `Upgrade (+${money(p.deltaCents)})`}
            </button>
          </div>
        ))}
      </div>
      {err && <p className="mt-2 text-xs text-amber-300">{err}</p>}
    </div>
  );
}

