  const [notice, setNotice] = useState<string | null>(null);
  const [dragOver, setDragOver] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [pending, start] = useTransition();

  const fileInputRef = useRef<HTMLInputElement>(null);

  const load = useCallback(
    (target: string) => {
      setLoading(true);
      setError(null);
      start(async () => {
        const res = await hostingListFiles(accountId, target);
        if (res.error) {
          setError(res.error);
        } else {
          setPath(res.path ?? target);
          setEntries(res.entries ?? []);
        }
        setLoading(false);
      });
    },
    [accountId],
  );

  useEffect(() => {
    load(ROOT);
  }, [load]);

  const refresh = useCallback(() => load(path), [load, path]);

  function flash(msg: string) {
    setNotice(msg);
    setTimeout(() => setNotice(null), 3000);
  }

  // ---- Breadcrumbs (rooted at public_html) ----
  const crumbs = (() => {
    const parts = path.split("/").filter(Boolean);
    const out: { label: string; path: string }[] = [];
    let acc = "";
    for (const p of parts) {
      acc = acc ? `${acc}/${p}` : p;
      out.push({ label: p, path: acc });
    }
    if (out.length === 0) out.push({ label: ROOT, path: ROOT });
    return out;
  })();

  // ---- Uploads ----
  const uploadFiles = useCallback(
    async (files: FileList | File[]) => {
      const list = Array.from(files);
      if (list.length === 0) return;
      setUploading(true);
      setError(null);
      let failed = 0;
      for (const file of list) {
        try {
          const fd = new FormData();
          fd.set("file", file);
          const res = await fetch(`/api/hosting/files?accountId=${accountId}&path=${encodeURIComponent(path)}`, { method: "POST", body: fd });
          if (!res.ok) {
            failed++;
            const body = await res.json().catch(() => ({}));
            setError(body.error || `Upload failed for ${file.name}.`);
          }
        } catch {
          failed++;
          setError(`Upload failed for ${file.name}.`);
        }
      }
      setUploading(false);
      if (failed === 0) flash(`Uploaded ${list.length} file${list.length === 1 ? "" : "s"}.`);
      refresh();
    },
    [accountId, path, refresh],
  );

  const onDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(false);
    if (e.dataTransfer.files?.length) uploadFiles(e.dataTransfer.files);
  };

  // ---- Mutations ----
  function newFolder() {
    const name = window.prompt("New folder name:");
    if (!name) return;
    setError(null);
    start(async () => {
      const res = await hostingMkdir(accountId, path, name);
      if (res.error) setError(res.error);
      else { flash("Folder created."); load(path); }
    });
  }

  function remove(entry: FsEntryView) {
    const what = entry.isDir ? "folder and everything inside it" : "file";
    if (!window.confirm(`Delete this ${what}? "${entry.name}" cannot be recovered.`)) return;
    setError(null);
    start(async () => {
      const res = await hostingDeleteFile(accountId, `${path}/${entry.name}`, entry.isDir);
      if (res.error) setError(res.error);
      else { flash("Deleted."); load(path); }
    });
  }

  const busy = pending || loading;

  return (
    <div className="space-y-4">
      {/* Toolbar */}
      <div className="card flex flex-wrap items-center justify-between gap-3">
        <div className="min-w-0 flex flex-wrap items-center gap-1 text-sm">
          {crumbs.map((c, i) => (
            <span key={c.path} className="flex items-center gap-1">
              {i > 0 && <span className="text-slate-600">/</span>}
              <button
                type="button"
                onClick={() => load(c.path)}
                className={`rounded-lg px-2 py-1 font-mono text-xs transition-colors hover:bg-white/[0.06] ${
                  i === crumbs.length - 1 ? "text-brand-300" : "text-slate-400"
                }`}
              >
                {c.label}
              </button>
            </span>
          ))}
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <button type="button" className="btn-secondary px-3 py-1.5 text-sm" onClick={() => fileInputRef.current?.click()} disabled={uploading}>
            {uploading ? "Uploading…" : "Upload"}
          </button>
          <button type="button" className="btn-secondary px-3 py-1.5 text-sm" onClick={newFolder} disabled={busy}>
            New folder
          </button>
          <button type="button" className="btn-ghost px-3 py-1.5 text-sm" onClick={refresh} disabled={busy} title="Refresh">
            Refresh
          </button>
          <input
            ref={fileInputRef}
            type="file"
            multiple
            className="hidden"
            onChange={(e) => {
              if (e.target.files?.length) uploadFiles(e.target.files);
              e.target.value = "";
            }}
          />
        </div>
      </div>

      {notice && (
        <div className="rounded-xl border border-emerald-500/30 bg-emerald-500/10 px-4 py-2 text-sm text-emerald-300">{notice}</div>
      )}
      {error && (
        <div className="rounded-xl border border-red-500/30 bg-red-500/10 px-4 py-2 text-sm text-red-300">{error}</div>
      )}

      {/* File listing (also the drop target) */}
      <div
        className={`card p-0 transition-colors ${dragOver ? "border-brand-400/60 bg-brand-500/[0.06]" : ""}`}
        onDragOver={(e) => { e.preventDefault(); setDragOver(true); }}
        onDragLeave={() => setDragOver(false)}
        onDrop={onDrop}
      >
        <div className="flex items-center justify-between px-4 pt-4">
          <p className="section-label">Files</p>
          <p className="text-xs text-slate-500">Drag &amp; drop files here to upload</p>
        </div>

        {loading ? (
          <div className="space-y-2 p-4">
            <div className="skeleton h-8 w-full" />
            <div className="skeleton h-8 w-full" />
            <div className="skeleton h-8 w-2/3" />
          </div>
        ) : (
          <table className="table-shell mt-2">
            <thead>
              <tr>
                <th>Name</th>
                <th className="text-right">Size</th>
                <th>Modified</th>
                <th className="text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {path !== ROOT && (
                <tr>
                  <td colSpan={4}>
                    <button
                      type="button"
                      className="flex items-center gap-2 text-sm text-slate-400 hover:text-white"
                      onClick={() => load(parentOf(path))}
                    >
                      <FolderIcon />
                      <span className="font-mono">..</span>
                    </button>
                  </td>
                </tr>
              )}
              {entries.map((entry) => (
                <tr key={entry.name}>
                  <td>
                    {entry.isDir ? (
                      <button
                        type="button"
                        className="flex items-center gap-2 text-left hover:text-white"
                        onClick={() => load(`${path}/${entry.name}`)}
                      >
                        <FolderIcon />
                        <span className="font-medium">{entry.name}</span>
                      </button>
                    ) : (
                      <a
                        className="flex items-center gap-2 text-left text-slate-200 hover:text-white"
                        href={`/api/hosting/files?accountId=${accountId}&path=${encodeURIComponent(`${path}/${entry.name}`)}`}
                      >
                        <FileIcon />
                        <span>{entry.name}</span>
                      </a>
                    )}
                  </td>
                  <td className="text-right text-slate-400">{entry.isDir ? "—" : fmtBytes(entry.size)}</td>
                  <td className="text-slate-400">{fmtWhen(entry.modified)}</td>
                  <td>
                    <div className="flex items-center justify-end gap-1">
                      {!entry.isDir && (
                        <a
                          className="btn-ghost px-2 py-1 text-xs"
                          href={`/api/hosting/files?accountId=${accountId}&path=${encodeURIComponent(`${path}/${entry.name}`)}`}
                        >
                          Download
                        </a>
                      )}
                      <button type="button" className="btn-danger px-2 py-1 text-xs" onClick={() => remove(entry)} disabled={busy}>
                        Delete
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
              {entries.length === 0 && (
                <tr>
                  <td colSpan={4} className="px-4 py-8 text-center text-sm text-slate-500">
                    This folder is empty. Upload your site files here, or install an app.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

